import{_ as i,o as t,c as n,a3 as s}from"./chunks/framework.DEy3KOfk.js";const g=JSON.parse('{"title":"@pumpkin-plugins/plugin-kit","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/plugin-kit/README.md"},"headers":[],"relativePath":"tools/plugin-kit/README.md","filePath":"tools/plugin-kit/README.md","lastUpdated":1791354672000}'),a={name:"tools/plugin-kit/README.md"};function o(r,e,l,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="pumpkin-plugins-plugin-kit" tabindex="-1">@pumpkin-plugins/plugin-kit <a class="header-anchor" href="#pumpkin-plugins-plugin-kit" aria-label="Permalink to &quot;@pumpkin-plugins/plugin-kit&quot;">​</a></h1><p>Shared building blocks for plugins: a common plugin base and registration wrapper, data folders, logging, scheduled tasks, command registration, plugin messages and binary payload encoders, plus in-memory fakes for tests. <code>PluginBase</code> derives Pumpkin metadata from <code>src/info.ts</code>, runs common lifecycle behavior, and <code>registerPlugin</code> starts the nonblocking Market update check after loading. Plugin entry points export <code>handleTask</code> from the shared plugin module to dispatch the check&#39;s polling tasks.</p><p>The scheduling helpers accept whole, nonnegative tick counts; repeating periods must be at least one tick. <code>cancelTask</code> cancels either delayed or repeating tasks and releases their callbacks. Delayed callbacks are also released before they run, and failed scheduling retains no callback.</p><p>Use <code>colorLogValue</code> from <code>@pumpkin-plugins/plugin-kit/logger</code> for a few values worth scanning, such as names, filenames, URLs, versions, UUIDs and ports. Follow the <a href="./../../docs/code-style#console-log-colors">console color convention</a>, which links to the pinned Pumpkin source for its palette and ANSI handling.</p><p><code>WasiDataDir.writeFile</code> replaces files through an exclusively created temporary sibling. Failed writes and renames clean up that sibling without replacing the original error. Directory creation checks that existing entries are directories; removing a symlink removes the link itself. Random-access file handles reject invalid read ranges and can be closed more than once.</p><p>The <code>MemoryFiles</code> test fake copies bytes at its boundaries, rejects file/directory conflicts and nonempty directory removal, and enforces file-handle closure. Use <code>put</code> to seed fixtures with missing parents; <code>writeFile</code> requires its parent directory to exist, matching the WASI adapter.</p><p>An internal package of <a href="https://github.com/filiphsps/pumpkin-plugins" target="_blank" rel="noreferrer">pumpkin-plugins</a>: it is not published to npm, and the plugins in this repo use it as a workspace dependency. See <a href="./../../docs/code-style">the docs</a> for how it is used, and the <a href="https://filiphsps.github.io/pumpkin-plugins/api/tools/@pumpkin-plugins/plugin-kit/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p>',7)])])}const h=i(a,[["render",o]]);export{g as __pageData,h as default};
